type Channel[T any] struct { mu sync.Mutex; subs map[chan T]struct{} }

func (c *Channel[T]) Subscribe() chan T {
    ch := make(chan T, 16)
    c.mu.Lock(); c.subs[ch] = struct{}{}; c.mu.Unlock()
    return ch
}

func (c *Channel[T]) Publish(v T) {
    c.mu.Lock(); defer c.mu.Unlock()
    for ch := range c.subs { select { case ch <- v: default: /* overflow policy */ } }
}
